<original_code>
#include <bits/stdc++.h>

#define dbg(x) cerr << #x << " = " << (x) << endl
#define separator cerr << "-------------------" << endl

using namespace std;

typedef long long ll;

struct step {
	ll val; int cost;
	bool operator<(const step &c) const {
		return c.cost < cost;
	}
};

set<ll> visited;

bool hasVisited(ll c) {
	return visited.count(c) > 0;
}

step getUpperBound(ll n){
	ll res = 0;
	int i = 0;
	while(res < n){
		res = res * 10 + 1;
		i++;
	}
	return {res, i};
}

step getUpper(ll n){
	ll res = 0;
	int i = 0;
	while(res * 10 + 1 <= n){
		res = res * 10 + 1;
		i++;
	}
	ll resmul = res;
	int imul = i;
	while(res < n){
		res += resmul;
		i += imul;
	}
	return {res, i};
}

step getLower(ll n){
	ll res = 0;
	int i = 0;
	while(res * 10 + 1 <= n){
		res = res * 10 + 1;
		i++;
	}
	ll resmul = res;
	int imul = i;
	while(res + resmul <= n){
		res += resmul;
		i += imul;
	}
	return {res, i};
}

int main() {
	ll n;
	cin >> n;

	priority_queue<step> pq;

	pq.push({n, 0});

	while(pq.top().val != 0){
		ll val = pq.top().val;
		int cost = pq.top().cost;
		pq.pop();

		if(hasVisited(val))
			continue;
		visited.insert(val);

		for (step s : { getLower(val), getUpper(val), getUpperBound(val) }) {
			s.cost += cost;
			s.val = abs(val - s.val);
			pq.push(s);
		}
	}

	cout << pq.top().cost << endl;
}
